select psi.id, psid.id as detailId, psi.code, psid.purchase_order_detail_id AS purchaseOrderDetailId, psi.purchase_order_id AS purchaseOrderId, psi.purchase_order_code AS purchaseOrderCode, psi.supplier_name AS supplierName, psi.approve_status AS approveStatus, psi.invalid_status AS invalidStatus, psid.sku_id AS skuId, psid.sku_no AS skuNo, psi.stock_in_date AS stockInDate, psi.purchase_user_name AS purchaseUserName, psi.stock_in_user_name AS stockInUserName, psi.approve_user_name AS approveUserName, psi.approve_time AS approveTime, psi.create_user_name AS createUserName, psi.create_time AS createTime, psid.purchase_qty AS purchaseQty, psid.stock_in_qty AS stockInQty, psid.exceed_qty AS exceedQty, psi.delivery_warehouse_id AS deliveryWarehouseId, psi.delivery_warehouse_name AS deliveryWarehouseName, psid.remark, COALESCE(pod.tax_rate,0) AS taxRate, COALESCE(pod.tax_price,0) AS taxPrice, COALESCE(pod.currency,'CNY') AS currency, COALESCE(pod.currency_symbol,'¥') AS currencySymbol, psi.subcontract_type as subcontractType, psi.purchase_type as purchaseType, psid.warehouse_location AS warehouseLocation from po_instock psi inner join po_instock_detail psid on psi.id = psid.main_id and psid.is_deleted = false left join purchase_order_detail pod on pod.id=psid.purchase_order_detail_id and pod.is_deleted = false where ${params.sqlMap.default} and psi.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
psi.create_time desc

select
count(distinct psi.id)
from po_instock psi
left join po_instock_detail psid on psi.id = psid.main_id and psid.is_deleted = false

    psi.is_deleted = false

        and psi.approve_status in

            #{item}



        and psi.stock_in_date >= #{params.stockInDateList[0]} AND (#{params.stockInDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > psi.stock_in_date


        and psi.invalid_status = #{params.invalidStatus}


        ${params.permissionSql}

