select psi.code, psi.supplier_name, psi.approve_status, psi.invalid_status, psid.sku_id, psid.sku_no, psi.stock_in_date, psid.stock_in_qty, psid.exceed_qty, psi.delivery_warehouse_name, psi.purchase_user_name, psi.stock_in_user_name, psid.remark, psid.purchase_order_detail_id from po_instock psi INNER JOIN po_instock_detail psid ON psi.id = psid.main_id AND psi.is_deleted = FALSE
psi.is_deleted = false
and psi.purchase_order_id = #{purchaseOrderId}

SELECT DISTINCT psi.id, psi.code, psi.source_id, psi.purchase_order_id, psi.source_type, psi.supplier_name, psi.delivery_warehouse_name, psi.approve_status, psi.subcontract_type as subcontractType, psi.create_time FROM po_instock psi left join po_instock_detail psid on psi.id = psid.main_id and psid.is_deleted = false WHERE psi.is_deleted = false AND psi.invalid_status = false
AND psi.code = #{params.code}
and psi.approve_status in
#{item}
and psi.stock_in_date >= #{params.stockInDateList[0]} AND (#{params.stockInDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > psi.stock_in_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY psi.create_time desc
